
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_mpw3pw_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_mpw3pw", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.530452245136773e+00, -3.463977203265747e+00, -3.370861459809973e+00, -3.241940120730036e+00, -3.066410299753623e+00, -2.833093465603974e+00, -2.533419635758990e+00, -2.166779767629532e+00, -1.747626214267763e+00, -1.309073068740047e+00, -8.899139670585376e-01, -6.134686125087206e-01, -5.342157600479318e-01, -4.410879193440674e-01, -3.199626389322045e-01, -2.047583504060219e-01, -1.174814282591965e-01, -4.123249087562161e-02, -2.767736312105966e-03, -3.260908624841968e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


